$questions = @(
    @{id="rea_001"; text="Tell me about your first listing. How did you approach the seller consultation?"; category="behavioral"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Prepared CMA and market data","Built rapport with seller","Presented value proposition clearly","Addressed concerns with data"); strong_answer_signals=@("Data-driven pricing discussion","Clear presentation skills","Client trust established"); avoid=@("Overpricing without market data","Generic pitch","Not addressing seller concerns")}}
    @{id="rea_002"; text="Describe a time you hosted an open house. How did you maximize buyer traffic and qualify leads?"; category="situational"; seniority=@("entry","mid"); answer_framework=@{structure="STAR"; key_points=@("Pre-marketed the open house across channels","Qualified buyers on arrival","Created a welcoming staging environment","Followed up with all attendees within 24 hours"); strong_answer_signals=@("High attendance-to-offer conversion","Effective lead qualification","Strong follow-up discipline"); avoid=@("No pre-marketing plan","Ignoring unqualified visitors","Zero follow-up after the event")}}
    @{id="rea_003"; text="Walk me through your process for conducting a Comparative Market Analysis (CMA). What data sources do you rely on?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Gathers recent comparable sales within 0.5 miles and 3-6 months","Adjusts for square footage, condition, lot size, and upgrades","Reviews active, pending, and expired listings for context","Validates against county tax records and MLS data","Presents findings in a clear, client-facing format"); strong_answer_signals=@("Precise comparable selection","Transparent methodology","Confident price-defending rationale"); avoid=@("Relying solely on automated estimates","Ignoring expired listings","No adjustments between comparables")}}
    @{id="rea_004"; text="How do you approach property valuation for a unique or unconventional home where few comparables exist?"; category="technical"; seniority=@("mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Expands the radius and time frame for comparables","Uses cost-approach and income-approach as supplements","Highlights unique features that add or subtract value","Consults with appraisers or local experts for validation","Communicates valuation uncertainty honestly to the client"); strong_answer_signals=@("Multi-method valuation approach","Honest about uncertainty","Willing to seek expert input"); avoid=@("Guessing a price without methodology","Ignoring the unique nature of the property","Over-relying on automated valuations")}}
    @{id="rea_005"; text="Explain the financing options you discuss with buyers. How do you guide them through pre-approval and loan selection?"; category="technical"; seniority=@("entry","mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Reviews conventional, FHA, VA, and USDA loan programs","Explains down payment, interest rate, and term trade-offs","Recommends lenders and pre-approval process upfront","Educates on closing costs, points, and PMI","Monitors loan progress and coordinates with the lender"); strong_answer_signals=@("Clear explanation of loan types","Proactive lender coordination","Educates rather than just recommends"); avoid=@("Pushing one lender without comparison","Not explaining loan terms","Ignoring buyer affordability limits")}}
    @{id="rea_006"; text="Describe your staging approach for a vacant home. What changes yield the highest ROI?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Declutters and deep-cleans before any staging","Adds neutral furniture and décor to define rooms","Uses light and mirrors to maximize perceived space","Focuses on curb appeal and first impressions","Stages each room with a clear purpose and focal point"); strong_answer_signals=@("Buyer-focused staging decisions","Strong ROI mindset","Attention to both interior and exterior"); avoid=@("Personalized or bold décor choices","Over-staging beyond the home's value tier","Neglecting curb appeal")}}
    @{id="rea_007"; text="How do you market a new listing across digital and traditional channels? What is your launch strategy?"; category="technical"; seniority=@("mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Launches professional photography, drone shots, and virtual tour within 24 hours","Posts on MLS, Zillow, Realtor.com, social media, and email campaign","Creates a dedicated listing webpage with SEO optimization","Sends just-listed emails to buyer database and sphere","Coordinates with showing assistants and broker syndication"); strong_answer_signals=@("Multi-channel launch executed fast","High-quality visual assets","Data-driven audience targeting"); avoid=@("Posting only on MLS with no photos","Delaying the market launch","Ignoring email and sphere outreach")}}
    @{id="rea_008"; text="What is your social media strategy for building your personal brand and generating leads?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Posts consistent content on Instagram, Facebook, LinkedIn, and TikTok","Shares market updates, neighborhood spotlights, and client stories","Uses video tours, behind-the-scenes content, and testimonials","Engages with followers through comments, stories, and reels","Tracks engagement metrics and refines content based on performance"); strong_answer_signals=@("Consistent posting schedule","Authentic personal brand","Platform-specific content optimization"); avoid=@("Posting inconsistently or sporadically","Only posting listings with no value content","Ignoring engagement and community interaction")}}
    @{id="rea_009"; text="Tell me about a negotiation where you represented a buyer. How did you handle a low-ball offer and counter-offers?"; category="situational"; seniority=@("mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Analyzed seller motivation and market conditions first","Crafted a strategic low-ball offer with comps to justify it","Communicated buyer's position clearly while preserving relationship","Managed multiple counter-offers and escalation clauses","Knows when to advise the buyer to walk away"); strong_answer_signals=@("Strategic offer positioning","Emotional composure under pressure","Clear communication of buyer's limits"); avoid=@("Offense without justification","Taking counter-offers personally","Not advising the buyer on walk-away points")}}
    @{id="rea_010"; text="Walk me through your process for writing a purchase contract. What key terms and contingencies do you include?"; category="technical"; seniority=@("entry","mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Verifies all party information and property details","Includes clear purchase price, earnest money, and closing date","Specifies contingencies: inspection, financing, appraisal, and title","Outlines repair requests and seller credits if applicable","Reviews deadlines and timelines with all parties"); strong_answer_signals=@("Meticulous attention to contract details","Clear contingency strategy","Proactive deadline management"); avoid=@("Missing key contingencies","Vague terms or undefined deadlines","Not reviewing contract with the client thoroughly")}}
    @{id="rea_011"; text="Describe your role during the closing coordination process. How do you ensure nothing falls through at the last minute?"; category="situational"; seniority=@("mid","senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Creates a closing timeline and shares it with all parties upfront","Coordinates inspections, appraisals, and repairs proactively","Communicates daily with lender, title company, and attorneys","Resolves last-minute issues like title defects or repair disputes","Attends the closing to ensure a smooth final process"); strong_answer_signals=@("Proactive issue resolution","Strong coordination across parties","Presence at closing"); avoid=@("Waiting until the last week to coordinate","Not attending the closing","Ignoring title or inspection red flags")}}
    @{id="rea_012"; text="How do you generate new leads consistently? What methods work best for you?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Leverages sphere of influence and past client referrals","Hosts community events and neighborhood meet-and-greets","Runs targeted digital ad campaigns on Facebook and Google","Implements a CRM system to nurture leads systematically","Pursues expired and FSBO listings proactively"); strong_answer_signals=@("Diversified lead generation strategy","Disciplined CRM follow-up","Consistent prospecting routine"); avoid=@("Relying solely on one lead source","Not following up with leads promptly","Neglecting sphere and past clients")}}
    @{id="rea_013"; text="Tell me about a time a client referred someone to you. How did you nurture that relationship and close the referral?"; category="behavioral"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Delivered exceptional service to earn the original client's trust","Responded to the referral immediately with a personalized outreach","Educated the referred client on market conditions and process","Kept the original client informed about the referral progress","Sent a thank-you gesture to the referring client"); strong_answer_signals=@("Quick response to referrals","Value-first communication","Gratitude toward the referrer"); avoid=@("Taking the referral for granted","Not following up promptly","Not acknowledging the referring client")}}
    @{id="rea_014"; text="How do you build and maintain long-term client relationships after the sale closes?"; category="motivation"; seniority=@("mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Sends anniversary and holiday cards to past clients","Shares market updates and neighborhood news periodically","Hosts client appreciation events annually","Stays top-of-mind through value-driven content","Asks for reviews and referrals at meaningful milestones"); strong_answer_signals=@("Genuine relationship investment","Consistent value delivery","Proactive outreach without being salesy"); avoid=@("Disappearing after closing","Only contacting when needing a listing","Generic mass emails with no personalization")}}
    @{id="rea_015"; text="How do you analyze a local real estate market? What metrics do you track and how do you use them?"; category="technical"; seniority=@("mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Tracks days on market, absorption rate, and months of supply","Monitors median sale price trends and price per square foot","Analyzes inventory levels and new listing volume","Studies interest rate impacts on buyer demand","Presents market snapshots to clients with actionable insights"); strong_answer_signals=@("Data-backed market insights","Clear translation of data to client action","Regular market updates and analysis"); avoid=@("Relying on anecdotal evidence only","Not tracking key metrics consistently","Presenting data without actionable advice")}}
    @{id="rea_016"; text="Describe your experience advising clients on investment properties. What factors do you consider?"; category="technical"; seniority=@("mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Analyzes cap rate, cash-on-cash return, and rental yield","Studies neighborhood growth indicators and development plans","Evaluates vacancy rates and tenant demand in the area","Reviews property management costs and maintenance reserves","Assesses appreciation potential and exit strategy options"); strong_answer_signals=@("Strong understanding of investment metrics","Focus on long-term returns","Educates the investor client"); avoid=@("Focusing only on appreciation","Ignoring rental demand and vacancy","Not calculating true investment returns")}}
    @{id="rea_017"; text="What do you know about commercial real estate basics? How would you approach a commercial listing?"; category="technical"; seniority=@("senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Understands lease structures: NNN, gross, modified gross, and percentage leases","Analyzes traffic counts, visibility, and accessibility for retail","Evaluates zoning laws, permit requirements, and usage restrictions","Reviews tenant creditworthiness and lease term stability","Knows the differences between residential and commercial transactions"); strong_answer_signals=@("Knowledge of commercial lease structures","Understanding of zoning and usage","Awareness of commercial-specific due diligence"); avoid=@("Applying residential approach to commercial","Not understanding lease terminology","Ignoring zoning and regulatory requirements")}}
    @{id="rea_018"; text="How would you handle property management responsibilities for a landlord client? What services do you provide?"; category="technical"; seniority=@("mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Conducts thorough tenant screening including credit and background checks","Manages lease agreements, rent collection, and eviction processes","Coordinates maintenance and repairs with vetted vendors","Provides monthly financial statements and property inspections","Ensures compliance with local landlord-tenant laws"); strong_answer_signals=@("Strong tenant screening process","Proactive maintenance management","Legal compliance awareness"); avoid=@("Skipping background checks","Delaying maintenance requests","Not staying current on landlord-tenant law")}}
    @{id="rea_019"; text="Walk me through a real estate math problem: If a property sells for $450,000 at a 6% commission split 70/30 between broker and agent, what does the agent earn?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Calculates total commission: $450,000 x 0.06 = $27,000","Splits commission: $27,000 x 0.70 = $18,900 to agent","Accounts for any franchise or desk fees if applicable","Explains the math clearly to the client","Verifies the final net amount after deductions"); strong_answer_signals=@("Accurate mental math","Clear step-by-step explanation","Transparency about deductions"); avoid=@("Incorrect commission calculation","Not explaining the split structure","Confusing gross and net amounts")}}
    @{id="rea_020"; text="What motivates you to succeed in real estate, and how do you plan to grow your career over the next five years?"; category="motivation"; seniority=@("entry","mid","senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Connects personal motivation to helping clients achieve life goals","Identifies specific areas for skill development and certifications","Sets measurable goals for income, client count, and team size","Plans to build a niche expertise in a specific market segment","Outlines steps toward leadership or brokerage ownership"); strong_answer_signals=@("Clear long-term vision","Specific and measurable goals","Alignment between motivation and action plan"); avoid=@("Only citing money as motivation","Vague goals without a plan","No commitment to ongoing education")}}
)

$json = @{metadata=@{sector="Real Estate Agent"; generated="2026-08-30"; total=20; schema_version="1.1"; categories=@("behavioral","technical","motivation","situational")}; questions=$questions}
$json | ConvertTo-Json -Depth 4 | Out-File -FilePath "D:\Claude\interview-aid-app\server\questions\real_estate_agent_questions.json" -Encoding UTF8NoBOM -Force
Write-Host "Real Estate Agent done!"